typedef struct { int type_id; } DataContext;

typedef int (*FuncPtr_Int)(DataContext*);
typedef float (*FuncPtr_Float)(DataContext*);

typedef struct OverloadTable {
    FuncPtr_Int process_int;
    FuncPtr_Float process_float;
} OverloadTable;

int DefaultInt(DataContext *ctx) { return ctx->type_id + 1; }
float DefaultFloat(DataContext *ctx) { return (float)ctx->type_id * 0.5f; }

const OverloadTable VTABLE = {
    .process_int = DefaultInt,
    .process_float = DefaultFloat
};

// Usage: VTABLE.process_int(&context_obj);
